package com.shijiangtai.m3classroom.domain.session;

import com.shijiangtai.shared.domain.ErrorCode;
import java.util.List;
import java.util.Objects;

/**
 * Result of one actor command: an ack plus the events generated by that command. Illegal
 * commands carry an {@link ErrorCode} and no events.
 */
public record CommandResult(boolean ok, List<SessionEvent> events, ErrorCode errorCode,
                            String message) {

    public CommandResult {
        events = events == null ? List.of() : List.copyOf(events);
    }

    public static CommandResult ok(List<SessionEvent> events) {
        return new CommandResult(true, events, null, null);
    }

    public static CommandResult error(ErrorCode errorCode, String message) {
        return new CommandResult(false, List.of(), Objects.requireNonNull(errorCode, "errorCode"),
                message);
    }
}
